from copy import deepcopy
from math import isfinite
from numbers import Real


class NearestMean:
    def __init__(self):
        self._dimensions = None
        self._centroids = None

    @staticmethod
    def _validated_rows(rows, dimensions=None, allow_empty=True):
        if not isinstance(rows, (list, tuple)):
            raise TypeError("rows must be a list or tuple")
        if not rows and not allow_empty:
            raise ValueError("rows must not be empty")
        result = []
        expected = dimensions
        for row in rows:
            if not isinstance(row, (list, tuple)):
                raise TypeError("each row must be a list or tuple")
            if expected is None:
                expected = len(row)
                if expected == 0:
                    raise ValueError("rows must have positive dimension")
            if len(row) != expected:
                raise ValueError("inconsistent row dimension")
            clean = []
            for value in row:
                if not isinstance(value, Real) or isinstance(value, bool):
                    raise TypeError("features must be real numbers")
                value = float(value)
                if not isfinite(value):
                    raise ValueError("features must be finite")
                clean.append(value)
            result.append(tuple(clean))
        return result, expected

    @staticmethod
    def _validated_labels(labels, expected_length):
        if not isinstance(labels, (list, tuple)):
            raise TypeError("labels must be a list or tuple")
        if len(labels) != expected_length:
            raise ValueError("rows and labels must have equal length")
        clean = []
        for label in labels:
            if not isinstance(label, str):
                raise TypeError("labels must be strings")
            if not label:
                raise ValueError("labels must be nonempty")
            clean.append(label)
        return clean

    def fit(self, rows, labels):
        clean_rows, dimensions = self._validated_rows(rows, allow_empty=False)
        clean_labels = self._validated_labels(labels, len(clean_rows))
        order = []
        sums = {}
        counts = {}
        for row, label in zip(clean_rows, clean_labels):
            if label not in sums:
                order.append(label)
                sums[label] = [0.0] * dimensions
                counts[label] = 0
            counts[label] += 1
            for index, value in enumerate(row):
                sums[label][index] += value
        centroids = {
            label: [value / counts[label] for value in sums[label]]
            for label in order
        }
        self._dimensions = dimensions
        self._centroids = centroids
        return self

    def predict(self, rows):
        if self._centroids is None:
            raise RuntimeError("model is not fitted")
        clean_rows, _ = self._validated_rows(rows, self._dimensions)
        predictions = []
        for row in clean_rows:
            best_label = None
            best_distance = None
            for label, centroid in self._centroids.items():
                distance = sum((a - b) ** 2 for a, b in zip(row, centroid))
                if best_distance is None or distance <= best_distance:
                    best_label, best_distance = label, distance
            predictions.append(best_label)
        return predictions

    def score(self, rows, labels):
        predictions = self.predict(rows)
        if not predictions:
            raise ValueError("cannot score empty rows")
        clean_labels = self._validated_labels(labels, len(predictions))
        return sum(a == b for a, b in zip(predictions, clean_labels)) / len(predictions)

    def model_snapshot(self):
        if self._centroids is None:
            return None
        return deepcopy({"dimensions": self._dimensions, "centroids": self._centroids})

